CREATE POLICY "Upload own CCTV" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'cctv-videos' AND (storage.foldername(name))[1] = auth.uid()::text); CREATE POLICY "Read own CCTV" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'cctv-videos' AND (storage.foldername(name))[1] = auth.uid()::text); CREATE POLICY "Delete own CCTV" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'cctv-videos' AND (storage.foldername(name))[1] = auth.uid()::text);